begin;
create extension if not exists pgtap with schema extensions;
select plan(13);
select ok((select relrowsecurity from pg_class where oid='public.account_deletion_jobs'::regclass),'deletion queue has RLS');
select ok(not has_table_privilege('authenticated','public.account_deletion_jobs','SELECT'),'queue is not browser readable');
select ok(not has_table_privilege('authenticated','public.request_limits','INSERT'),'limits cannot be forged');
select ok(not has_function_privilege('authenticated','public.take_request_slot(uuid,text,integer,integer)','EXECUTE'),'limiter is service only');
insert into auth.users(id,email) values('f1000000-0000-4000-8000-000000000001','lifecycle-one@example.test'),('f1000000-0000-4000-8000-000000000002','lifecycle-two@example.test');
select ok(take_request_slot('f1000000-0000-4000-8000-000000000001','export',1,3600),'first request allowed');
select ok(not take_request_slot('f1000000-0000-4000-8000-000000000001','export',1,3600),'repeated request throttled');
insert into learning_sessions(id,user_id) values('f2000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001');
insert into activities(id,user_id,session_id,activity_type,sequence_no,learning_purpose,difficulty_level,english_exposure_level,correction_strategy) values('f3000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','normal_learning',0,'communication',1,1,'delayed');
insert into voice_interactions(id,user_id,session_id,activity_id,interaction_type,audio_object_path,transcript) values('f4000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','tts','f1000000-0000-4000-8000-000000000001/test.mp3','preserved learning text');
select lives_ok($$update voice_interactions set audio_object_path=null,audio_deleted_at=now() where id='f4000000-0000-4000-8000-000000000001'$$,'cleanup can clear reference');
select is((select transcript from voice_interactions where id='f4000000-0000-4000-8000-000000000001'),'preserved learning text','cleanup preserves transcript');
insert into account_deletion_jobs(user_id) values('f1000000-0000-4000-8000-000000000001');
delete from auth.users where id='f1000000-0000-4000-8000-000000000001';
select is((select count(*)::int from profiles where user_id='f1000000-0000-4000-8000-000000000001'),0,'profile cascades');
select is((select count(*)::int from voice_interactions where user_id='f1000000-0000-4000-8000-000000000001'),0,'voice metadata cascades');
select is((select count(*)::int from account_deletion_jobs where user_id='f1000000-0000-4000-8000-000000000001'),1,'retry queue survives identity deletion');
select is((select count(*)::int from profiles where user_id='f1000000-0000-4000-8000-000000000002'),1,'other learner preserved');
select ok((select count(*)>0 from plans),'shared definitions preserved');
select * from finish();
rollback;
